import { ISongReference } from './song-reference.interface';

/**
 * A schedule reference auto-generated by the app (e.g. a Spotify playlist
 * created from a schedule). Extends ISongReference with sync metadata that
 * tracks the state of the generated artifact. The metadata is managed by
 * the API: clients can't change it through the schedule endpoints.
 */
export interface ISchedulePlaylistReference extends ISongReference {
  /** Which app feature generated this reference. */
  source: 'spotify-auto' | 'youtube-auto'
  syncedAt?: string
  tracksHash?: string
  /** Only sent to signed-in members. */
  syncedByName?: string
  /** Computed by the API for the requesting user. */
  syncedByMe?: boolean
}

/** Result of creating or re-syncing a schedule's generated playlist. */
export interface ISchedulePlaylistSyncResult {
  action: 'created' | 'synced'
  url: string
  added: number
  skipped: { songId: number; title: string }[]
}
